#include <string>

using namespace std;

class Solution {
public:
    int numSub(string s) {
        const int MOD = 1e9 + 7;
        long res = 0, count = 0;
        for (char c : s) {
            if (c == '1') count++;
            else {
                res += count * (count + 1) / 2;
                count = 0;
            }
        }
        res += count * (count + 1) / 2;
        return res % MOD;
    }
};
